11	// approvalPolicy 构造一条开启大额审批的策略：门槛 10，等待 1 分钟，
12	// 其余与 validPolicy 一致（单次 30、累计 50、窗口 1 小时）。
13	func approvalPolicy(c *clock) PolicySpec {
14		p := validPolicy(c)
