619		req, err := w.Apply(in)
620		if err != nil {
621			t.Fatal(err)
622		}
623		if !req.WaitDeadline.Equal(c.t.Add(30 * time.Second)) {
624			t.Fatalf("deadline = %v, want policy end %v", req.WaitDeadline, c.t.Add(30*time.Second))
625		}
