627		// 场景 2：会话到期早于等待时长 → 期限取会话到期。
628		w2, c2 := setupApproval(t)
629		sessExp := c2.t.Add(20 * time.Second)
630		if _, err := w2.CreateSession("s-short", "u1", "dev1", sessExp); err != nil {
631			t.Fatal(err)
632		}
